import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/LempelZiv.html","title":"LempelZiv","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.44,"words":132},"filePathRelative":"LempelZiv.md"}`),a={name:`LempelZiv.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="lempelziv" tabindex="-1"><a class="header-anchor" href="#lempelziv"><span>LempelZiv</span></a></h1><p><a href="./CoverAndThomas.html">CoverAndThomas</a>の13.4より。</p><p>1977年の論文のLZ77 (Sliding Window)と1978年のLZ78 (ツリー）がある。分布が分かっていないケースの圧縮。<a href="./データ圧縮.html">データ圧縮</a></p><h2 id="sliding-window-lempel-ziv-lz77" tabindex="-1"><a class="header-anchor" href="#sliding-window-lempel-ziv-lz77"><span>Sliding Window Lempel-Ziv (LZ77)</span></a></h2><p>i番目を考える。i番目から先の文字列を、i-1からWだけ戻ってる範囲（i-1-W）で探して、その位置P（iからどれだけ戻るか）と長さLを送る。 次はi+L+1から始める。</p><p>Wの範囲で一致する文字列が無ければそのまま文字を送る。</p><p>どちらのケースか表すフラグを1bit、それと一致があればP, L, 無ければCが送られる。</p><ul><li>(F, P, L)</li><li>(F, C)</li></ul><p>これがSliding WindowバージョンのLZ77。 オーバーラップするケースがあると言っているがその場合はオーバーラップした文字列は送られないのでは？という気もするがどうなっているのだろう？</p><p><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78" target="_blank" rel="noopener noreferrer">LZ77 and LZ78 - Wikipedia</a> を読むと、越えた分はそれまでのパターンを繰り返していくらしい。</p><p>これはgzipやpkzipで使われているとか。</p><h2 id="tree-structured-lempel-ziv-lz78" tabindex="-1"><a class="header-anchor" href="#tree-structured-lempel-ziv-lz78"><span>Tree-Structured Lempel-Ziv (LZ78)</span></a></h2><p>そこまででてきたprefix+1文字、を送り続ける。prefixは先頭からのオフセット。ツリーを作る事に相当する。</p><p>Unixのcompressやgifで使われているとか。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};